<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     iActivatorPunishInterval;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 惩罚期重试间隔</span></span>
